actions.script:
let baseUrl = ''
if (webHostName) {
    baseUrl = 'https://' + webHostName
} else {
    const rootUrl = ec.web.getWebappRootUrl(sri?.webappName || 'webroot', null, true, false)
    if (rootUrl && !rootUrl.includes('localhost')) baseUrl = rootUrl
}
const digestRows = (notificationList || []).map((nm) => {
    let linkUrl = nm.link || ''
    if (linkUrl && !linkUrl.startsWith('http') && baseUrl)
        linkUrl = baseUrl.replace(/\/$/, '') + (linkUrl.startsWith('/') ? '' : '/') + linkUrl
    return Object.assign({}, nm, {linkUrl: linkUrl})
})
// first-seen order; the Maps stay local so the template sees only appName and topics
const groups = []
const byApp = new Map()
for (const row of digestRows) {
    const appName = row.appName || ''
    let app = byApp.get(appName)
    if (!app) {
        app = {appName: appName, topics: [], byTopic: new Map()}
        byApp.set(appName, app)
        groups.push(app)
    }
    const topicKey = row.topic || ''
    let topic = app.byTopic.get(topicKey)
    if (!topic) {
        topic = {topic: topicKey, topicDescription: row.topicDescription || topicKey, rows: []}
        app.byTopic.set(topicKey, topic)
        app.topics.push(topic)
    }
    topic.rows.push(row)
}
digestGroups = groups.map((app) => ({appName: app.appName, topics: app.topics}))
digestTitle = ec.l10n.localize('Your notifications') + ' (' + (notificationCount || digestRows.length) + ')'

render-mode.text:
${digestTitle}

<#list digestGroups as app>
<#if app.appName>${app.appName}

</#if>
<#list app.topics as topic>
  ${topic.topicDescription ?? ""}
<#list topic.rows as nm>
    ${nm.title}
      ${nm.topicDescription ?? ""} - ${nm.sentText ?? ""}<#if nm.linkUrl>
      ${nm.linkUrl}</#if>

</#list>
</#list>
</#list>
